def metrics(correct, minor, wrong):
    total = correct + minor + wrong
    if total == 0:
        return {'accuracy': 0.0, 'harm_rate': 0.0, 'acceptable': 0.0}
    return {
        'accuracy': round(correct / total, 3),
        'harm_rate': round(wrong / total, 3),
        'acceptable': round((correct + minor) / total, 3),
    }
